    "pregunta": "Para el diagnóstico del síndrome de Cushing se está evaluando la capacidad discriminatoria de una nueva magnitud bioquímica, con los siguientes resultados: entre los pacientes con test positivo, 20 están sanos (falsos positivos) y 40 están enfermos (verdaderos positivos); entre los pacientes con test negativo, 80 están sanos (verdaderos negativos) y 20 están enfermos (falsos negativos). ¿Cuál es la eficiencia diagnóstica de dicha magnitud?",
