      "a": "No corresponde al cálculo correcto de la eficiencia diagnóstica con estos datos.",
      "b": "La eficiencia diagnóstica se calcula como (verdaderos positivos + verdaderos negativos) / total = (40 + 80) / 160 = 120/160 = 75%.",
      "c": "Sería el resultado si solo se considerasen los verdaderos positivos sobre el total de positivos y negativos de un único grupo, un cálculo incorrecto para la eficiencia global.",
