      "b": "Es la afirmación falsa: al bloquearse la glucólisis disminuye, no aumenta, la síntesis de ATP, precisamente porque esta vía es la fuente energética casi exclusiva del eritrocito.",
      "c": "Sí es cierto: por su dependencia casi exclusiva de la glucólisis, el eritrocito es la célula más afectada por estos defectos.",
      "d": "Sí es cierto: la falta de energía compromete la membrana eritrocitaria y favorece su destrucción prematura."
