"opciones": { "a": "Un componente celular (fibroblastos, osteoblastos/osteoclastos, adipocitos, células endoteliales) y un componente extracelular (colágeno, fibronectina, glucosaminoglucanos, laminina)", "b": "Únicamente eritrocitos maduros", "c": "Únicamente plaquetas circulantes", "d": "Ninguna estructura extracelular relevante" },
