"pregunta": "¿Qué diferencia principal existe entre los eosinófilos y los neutrófilos en cuanto a su papel inmunológico predominante?",
"opciones": { "a": "Los eosinófilos se especializan sobre todo en la defensa antiparasitaria y la modulación alérgica, mientras que los neutrófilos actúan principalmente frente a bacterias y hongos", "b": "Ambos tienen exactamente la misma función y no existe ninguna diferencia entre ellos", "c": "Los eosinófilos son los leucocitos más abundantes de la sangre, más incluso que los neutrófilos", "d": "Los neutrófilos son mononucleares y los eosinófilos son polimorfonucleares" },
