"b": "Incorrecta. Aunque comparten origen mieloide y estructura polimorfonuclear, tienen funciones inmunológicas predominantes claramente diferenciadas.",
"c": "Incorrecta. Los neutrófilos son mucho más abundantes que los eosinófilos en la sangre periférica normal.",
"d": "Incorrecta. Ambos son granulocitos polimorfonucleares; ninguno de los dos es mononuclear."
